      "ホーム画面タップ２": "そんなチラチラ見ずとも、この若返った吾の素晴らしいボディーを存分に眺めるがよい！よくわかっておるではないか！",
      "ホーム画面タップ３": "この尻尾か？好きなやつを見ると、つい振ってしまうんだ。触ってみるか？",
      "ホーム画面下着状態": "もぐもぐ…おい、もう少し近くに来い、食べさせてくれるならちゃんと吾を見てろ。",
