      "プレゼント-感謝2": "たまにはこういうのもいいものだな。んん？お前から貰ったからに決まってるだろ。",
      "プレゼント-感謝3": "急にこんないいものをくれるなんてどうしたんだ？吾がなんでも望みを叶えてやるぞ！尻尾も耳も、胸だって触っていいからな！",
