      "ホーム画面下着タップ1": "ああ、城主閣下が気絶した！鼻血も出ている！こ、これは中毒！？",
      "ホーム画面下着タップ2": "今日もいい天気だね...なぜまた変な目で見つめる？",
      "ランクアップ": "この感じは...力が強くなったね。",
