      "ultimate": {
        "name": "聖なる十字・神威・霞切り",
        "text": "効果：\n・敵横一列を攻撃し、３５０％のダメージを与える。\n・２ターンの間、自身の増傷＋２０％、減傷＋２０％、会心抵抗率＋２０％、ブロック率＋２０％。\n・「聖なる盾」最大値の５％×戦場に残っている味方キャラ数の「聖なる盾」を回復する。\n・目標に目標の最大HPの２.５％と自身が持っている「聖なる盾」の１５％の追加ダメージを与える（PVE無効）。\n・敵全体に「弱化」をかけ、味方全体に「鼓舞」をかける。\n『用語』\n弱化：\n・２ターンの間、奥義減傷ー５％、スキル減傷ー５％、目標が前列にいる場合ー１０％となる。\n鼓舞：\n・２ターンの間、奥義増傷＋５％、増傷＋５％、目標が後列にいる場合１０％となる。\nポイント：\n奥義後に味方全体にバフを、敵全体にデバフをかけれるのが強力です。\nまた、自身のステータスを大幅にアップ出来る点も強力です。\nさらに、聖なる盾を回復できる点も優秀です。\n目標の最大HPに応じた割合ダメージを与えれる点が強いです。"
      },
      "evolution": {
        "fire": [
          "Lv1: 騎士の盾\n効果：スキル（光の三段突き・覚）に以下の効果を追加する。\n・「聖なる盾」最大値の１０％×戦場に残っている味方キャラ数の「聖なる盾」を回復する。\n・５０％の確率で目標に「挑発」をかける。\n・自身のコントロール抵抗率＋１０％、防御＋１０％、戦闘終了まで有効、最大４回重ね合わせ可能、解除不可。\n \n『用語』\n挑発：\n・目標は奥義とスキルを発動できず、強制的にガウェインに通常攻撃する。効果は１タ",
          "Lv2: 追い風\n\n効果：パッシブ（万能騎士・覚）に以下の効果を追加する。\n・自身のブロック強度＋２０％、会心抵抗率＋２０％。\n・最大限の「聖なる盾」を持っている状態で、敵からの奥義、スキル、通常攻撃された場合、爆発を起こせる。\n・「聖なる盾」の爆発によって、敵全体にガウェインの最大HPの２.５％の追加ダメージを与える。（ターン毎に２回のみ発動可能）。\n・自身が死亡する時（復活や死亡しないなどの効果の触発を",
          "Lv3: 神聖浄化\n\n \n効果：パッシブ（万能騎士・覚）に以下の効果を追加する。\n・自身の攻撃＋１０％、防御＋１０％。\n・致命ダメージによる死亡しない効果の発動可能回数が２回まで増加する。\n・ガウェインが「聖なる盾」を持っている場合、行動する前にランダムで味方全体のデバフ効果を１つ解除する。\n・１つのデバフ効果を解除するごとに、「聖なる盾」最大値の２％を回復する。\n・「聖なる盾」の爆発は敵全体を１ターンの間"
        ],
        "ice": []
      }
