          "Lv2: 領域練成\n\n\n\n\n効果：パッシブ（不死の探究者・覚）に以下の効果を追加する。\n・攻撃力＋２０％、防御力＋２０％、減傷＋１０％、奥義増傷＋１０％、奥義減傷＋１０％。\n・「神話の力」が１０点以上の場合、ギルガメッシュは２０％の生命極限を持ち、HPは最大HPの２０％以下に減少しない。\n・HPが２０％以下になるダメージを受けた後、現在持っている半数の「神話の力」を消耗し（最少消耗数は１５点）、自身のすべて",
          "Lv3: 恵みの雨\n\n\n効果：奥義（不滅秘宝・黄金の矢・煌き）に以下の効果を追加する。\n・味方全体にギルガメッシュの攻撃力の１００％分のHPを回復する。\n・ギルガメッシュが前列にいる場合、さらに減傷＋１０％、攻撃を受けた後、同行の味方キャラが損失したHPの１０％を回復させ（最少は目標の最大HPの５％）、効果は２ターン持続する。\n・コントロール効果を受けている１名の味方キャラのすべてのデバフ効果を解除する。\n"
