        "text": "効果：\n・敵一体を攻撃し、３００％のダメージを与える。\n・自身のコントロール率＋２０％、効果は２ターン持続する。\n・８０％の確率で目標に「無援」効果をつける。\n『用語』\n無援：\n・目標はブロックできない。\n・効果は２ターン持続する。\nポイント：\n８０％の確率でブロックできない様にさせる点がとても強力です。\n自身のコントロール率を高めれる点が強力です。"
