        "text": "SSR時との違い：\n「神聖な恩賜」によりキャラが復活する確率が２０％から２５％にアップ。\n『用語』\n神聖な恩賜：\n・キャラが死亡すると、２５％の確率で次のターン開始時に復活できる。\n・復活後、当該キャラの最大HPの３０％まで回復し、さらにキャラが死亡時の戦意を１００％継承できる。\n・効果は戦闘終了まで有効、各キャラは戦闘毎に１回のみ発動可能、解除不可、また吸い取られることもない。\nポイント：\n確率ですが、死亡した味方を復活できる効果を付与できる点が強力です。\n被ダメージを減少させることが出来る強靭が大幅に上がるのが強力です。\n確率ですが、行動前に自身にかけられているコントロール効果を１つ解除できる点が強力です。\n条件はありますが、味方が死亡した時にHPと戦意を回復できるのがとても強いです。"
