          "Lv2: 光の信仰\n\n\n効果：パッシブ（愛の光・覚）に以下の効果を追加する。\n・最大HP＋３０％。\n・コンスタンティノスは行動する前に自身にかけられているコントロール効果の解除確率＋２５％。\n・味方ターン終了時に、HPのパーセンテージが一番低い味方２名（自身を含まない）に「魔法少女の祈り」をかける。\n \n『用語』\n魔法少女の祈り：\n・発動しようとしている全てのデバフ効果を有効になる前に、コンスタンティノスが",
