          "Lv2: 力を貸して\n\n\n効果：パッシブ（勇者ー覚）に以下の効果を追加する。\n・味方キャラが死亡するたびに、伊達政宗はそのキャラの１００％分の戦意を継承し、スキルをもって追加攻撃する。\n・もし戦意を継承する時にすでに５００戦意を持っている場合、そのキャラの攻撃力の２０％を継承でき、効果は戦闘終了まで有効。（伊達政宗の攻撃力がそのキャラの攻撃力より高いあるいはPVEの場合、そのキャラの攻撃力を継承せず、伊達政",
