    "cv": "あいりん",
    "role": "力智天敵、リーパー",
    "dialogues": {
      "召喚獲得": "趙子龍参る！タイマンならいつでもOKだよ！...あっ、できればレディーファーストで！",
      "ホーム画面タップ１": "勝手に触るな！…ってあれ？主君様？",
      "ホーム画面タップ２": "主君さま、ご命令は？この槍には相手が必要なんだ！",
      "ホーム画面タップ３": "僕がそばに居るんだから、主君様は好きなことし放題だよ！どっちのことかって？もちろん私生活の方だよ！",
      "ホーム画面下着状態": "ちょっと待て！まだ始まってもないのに、変なとこ触らないでよ！",
      "ホーム画面下着タップ1": "なにこれ…？アヒルのオモチャかな？それとも主君様の手？硬いものがずっと当たってるよ？",
      "ホーム画面下着タップ2": "これ以上は…待って、もうダメ…！止まらない…はあ！",
      "ランクアップ": "主君様を倒したいなら、まずはこの槍を超えてみせるんだな",
      "覚醒": "この力があれば、主君さまを守りながらイチャイチャできる！",
      "調教道具1": "------------------------------",
      "調教道具2": "------------------------------",
      "MVP宣言": "女の子もみーんな、僕が守るよ！",
      "プレゼント-挨拶": "主君さま、来てくれたんだ。",
      "プレゼント-感謝1": "では、いただくよ。",
      "プレゼント-感謝2": "とても役に立つものだ。",
      "プレゼント-感謝3": "女の子に分けてもいい？",
      "クローズアップ": "------------------------------",
      "スキル1": "くらえ！",
      "スキル2": "槍は龍が如く！",
      "スキル3": "豪気無双！",
      "奥義1": "千軍万馬の敵が居ようとも、敵将を討ち取ってみせる！",
      "奥義2": "女の子とのラブラブタイムを邪魔するんじゃない！",
      "死亡": "主君様、お逃げください…"
    }
