        "text": "効果：\n・敵一体を攻撃し、５００％のダメージを与え、その目標から２００点の戦意を吸収する。\n・主目標の周囲（上下左右）の敵に１００％のダメージを与え、それぞれ４０％の確率で「通電」をかける。\n・当該ターンで馬超は必ずスキルを発動できる。\nポイント：\n主目標に高いダメージを与えつつ、戦意を吸収できるのがとても強いです。\nまた、周囲の敵に行動不能効果のあるデバフを複数付与できる可能性があるのがとても強力です。\n奥義後にスキルを必ず発動できるのがとても強いです。"
