          "Lv2: 狂雷\n\n\n効果：パッシブ（錦服の貴公子・覚）に以下の効果を追加する。\n・スキル減傷＋３０％、奥義減傷＋３０％。\n・味方ターン終了時に、会心率＋５％、会心強度＋５％、奥義増傷＋５％、増傷＋５％、効果は戦闘終了まで有効、最大６回重ね合わせ可能、解除不可。\n・登場時に、馬超は以下の効果をそれぞれ１つ獲得し、さらに自身以外の味方キャラのタイプに基づき、追加で効果を１つ獲得可能、１種の効果につき最大３回重ね",
          "Lv3: 怒雷の墓\n\n\n\n効果：奥義（万雷・迅雷瞬殺陣・霹靂）に以下の効果を追加する。\n・馬超は奥義攻撃で敵を攻撃し、致命ダメージを与えた際に、もしその敵が復活や死亡しないなどの効果を持っている場合、それを無視して「怒雷の墓」として鎮圧する。\n・馬超は奥義攻撃で敵を攻撃し、致命ダメージを与えられなかった際に、「激雷の圧痕」をかける。\n・奥義ダメージは追加で２０％「黒血侵食」をつける。\n・奥義後２ターンの間、"
