          "Lv2: 新生の魔法\n\n\n効果：パッシブ（光と闇との融合－覚）に以下の効果を追加する。\n・自身の減傷、奥義減傷、会心抵抗を＋１５％追加、スキル発動率を＋２０％する。\n・登場または復活後２ターンの間、奥義減傷と回復効果が３０％アップする。\n・攻撃を受けた際に、自身のHPが４０％以下の場合、「新生の魔法」を発動する。\n \n新生の魔法：自身の全てのデバフを解除し、最大HPの１５％分の「黒血侵食」を癒す。\nまた、各",
          "Lv3: 祝福の魔法\n\n\n\n効果：奥義（究極サキュバスの舞－至高魅力の舞）に以下の効果を追加する。\n・奥義の回復効果と同時に敵全体に180％のダメージを与え、５０％の確率で「抑制の魔法」を１つ付ける。\n・命中した敵が３つの「抑制の魔法」を持っていたら、マーリンの戦意を最大まで回復する。\n・「黒血侵食」を持つ味方をマーリンの攻撃力の１５０％分癒す。\n・奥義発動時に「祝福の魔法」を２つ（１対１の戦闘の場合１つ）"
