          "Lv2: 天与の野生\n\n\n効果：パッシブ（双槍の騎士・覚）に以下の効果を追加する。\n・登場時に、戦場にいる敵のキャラ数の「野性味」を獲得する。\n・味方キャラが奥義を発動する時に、実際に与えたダメージからクーフーリンを治療でき、治療量はそのダメージの１％分（治療量はクーフーリンの最大HPの１％を超えない）、そして２０％の確率でクーフーリンの全てのデバフ効果を解除できる。\n・戦意が削減されると２００点の戦意を回",
