          "Lv2: 椿咲き\n\n\n効果：パッシブ（百花の騎士姫・覚）に以下の効果を追加する。\n・自身攻撃力＋３０％、最大HP＋３０％。\n・攻撃されるとき、６０％の確率でスキルをもって攻撃者に反撃する。\n・ネロの攻撃で目標を死亡に類する状態にした場合、ネロの最大HPを＋１０％し、同じ数値のHPを回復する。\n \n＊補足＊\nネロの最大HPが１０００で、現在HPが９００だとして、敵を死亡に類する状態にした場合\n１０００×０.１",
