          "Lv2: 任務・勇敢\n\n\n効果：パッシブ（冒険の神・覚）に以下の効果を追加する。\n・減傷＋１５％、奥義減傷＋１５％、会心抵抗率＋１５％。\n・ヘラクレスが１名の敵を攻撃するごとに、ヘラクレスはすぐに１スタックの「任務」と１スタックの「任務・勇敢」を完了する。\n \n『用語』\n任務・勇敢：\n・１スタック完了につき、自身の攻撃力＋２％、効果は２ターン持続する、今回の戦闘にて合計で２０回以上の「任務・勇敢」を完了した",
