    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA2MjlfMTkz/MDAxNjg4MDI1MDIyOTM5.ewLL9MG4ZgXh_ic8utN39qyqE4o-ocp3wgZNQZhcZAQg.2PoAiwNLUouuxlMseNcymYWp0DPNOs6ZNFrQSEHydPUg.JPEG/%EC%95%8C%EB%A0%89%EC%82%B0%EB%8D%94.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "人生はある指針を守ってこそ成り立つもの。あなたの混沌とした人生は、私が変えてあげましょう！初めまして、立花道雪です！よろしくお願いします。",
      "ホーム画面タップ１": "他人に触られるのは絶対嫌なのに、あなたに触れられても気持ち悪くならないのは珍しい。",
      "ホーム画面タップ２": "早朝５時に修行を始め、６時に日の出を見て、７時に朝食を取り、８時に....これが私の日課です。あなたもこれを毎日きっちり守りなさい。",
      "ホーム画面タップ３": "私は変化が好きではありません。それは元のルールを破ることを意味します。しかし、いい変化もあります。例えば、あなたに会えること。",
      "ホーム画面下着状態": "海水に入るのは最初で最後の体験にしましょう。これと比べたら、温泉の方が慣れていますから！",
      "ホーム画面下着タップ1": "なぜか突然、海の底に沈んでみたいという衝動に駆られました。危険だとわかっていながら、どうしても試してみたくなったのです。",
      "ホーム画面下着タップ2": "釣りをする際は、心の中で60秒まで数えてから竿を引き揚げるのが重要です！おっと、失敗しましたか。今度は必ず釣り上げます!",
      "ランクアップ": "雷の力は私が操ります！",
      "覚醒": "よくできました、ルールを守って修行を続けましょう！",
      "調教道具1": "------------------------------",
      "MVP宣言": "私が作ったルールは誰にも破れません！",
      "プレゼント-挨拶": "やっと会えました、毎日ここに立っているのが習慣になりました。",
      "プレゼント-感謝1": "とても美味しいのですが、先に手を洗って下さい。",
      "プレゼント-感謝2": "美食は必ず28回目まで噛んでから飲み込みます。",
      "プレゼント-感謝3": "いつも最初の一口は、一番真ん中から食べています。",
      "クローズアップ": "------------------------------",
      "スキル1": "ハ！",
      "スキル2": "イェイ！ハ！…",
      "スキル3": "雷霆の力！",
      "奥義1": "雷霆万鈞（らいていばんきん）",
      "奥義2": "雷霆を操り、すべてを破壊します！",
      "死亡": "このような退場は、私のルールに相応しくない！"
    },
