      "メインページでタップ２": "わたくし・・・実はスキンシップが嫌いでね。うん？意外かな？実際、わたくしに触れたことがある者は片手で数え切れぐらいしかいないわね。",
      "メインページでタップ３": "ひゃっ！あなたに警告したはずなのに！わたくしに勝手に触らないでよ！・・・万が一子供が出来たらどうしましょう！",
      "メインページでタップA1": "うっかりしちゃった、お風呂に入れる用の花びらを入れ忘れてしまったわ、どなたか助けてくださる優しい方いらっしゃらないのかしらね？（ちらっ）",
