    "dialogues": {
      "召喚獲得": "赤備隊！首領！武田信玄でござる！俺を見下した奴は容赦しない！思い知れ！",
      "メインページでタップ1": "おい、さっき背が小さいって笑ってたな？あぁ？ぶった切ってやる！",
      "メインページでタップ２": "クソ…馬はなぜこんな高いのかな…俺の身長にちょうどいい品種があれば良いのにな…",
      "メインページでタップ３": "お前、コソコソ何やってんだ……あっ！おやつだ！早くよこせ。あっ？食べたい訳じゃない、ちょうどお腹が空いただけだ！",
      "メインページでタップA1": "信玄様の実力を見たか！俺が手を下せば、猫や犬ぐらいなんぼのもんじゃ！",
      "メインページでタップ-下着1": "フン！武田信玄様の強さを見たか！このバカ猫！",
      "メインページでタップ-下着2": "俺の「新生赤備隊」の軍糧を盗むとはいい度胸だな！どう始末しようかな？猫鍋ってのはどうだ！",
      "星アップ": "これで、あのババアを地面に踏みつけられる、フフン……",
      "覚醒": "見たろう！これが我武田信玄之風林火山だ！",
      "親密アイテム1": "うわ！勝手に動くな！出ちゃう！見せられない所が出ちゃうよ！",
      "親密アイテム2": "お前はわざとだな！今日の屈辱は覚えたぞ、絶対に赦さないからな！",
      "MVP宣言": "新生赤備隊、前進！敵を皆踏み潰せ！",
      "スキル1": "俺をなめるな！",
      "スキル2": "ぶっ飛ばすぞ！",
      "奥義1": "どこを見てんだアホが？俺はここだぞ！",
      "奥義2": "これが俺信玄之必勝法だ！",
      "死亡SE": "うあ～"
    },
