    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "われが皇帝、ナポレオン＝ボナパルトだ。まああまり気にせずに、ナポレオンと呼べばよい、あくまでただのある城の帝なだけだ。",
      "メインページでタップ1": "将軍になりたくない兵はいい兵じゃない・・・か・・・でも結局、そう思う者は基本死んでるね・・・",
      "メインページでタップ２": "うん？私が無情すぎると？それはあいつらみんな私の敵だから。敵に優しいことこそ味方に対する無情だ。",
      "メインページでタップ３": "何か身長を早く伸ばせる方法はないか？私は気にしてないが・・・誰かが私のことをちびと言って処されるのが嫌でね。",
      "メインページでタップA1": "なんだ・・・なんでお前の目から残念そうな感じがするんだ？何か話があればよく考えてから話したほうがいいんじゃないか？",
      "メインページでタップ-下着1": "こんな時に日焼け止めを塗ってくれる人がいないのは不便だな・・・お？ちょうどよかった、早く手伝って。",
      "メインページでタップ-下着2": "どうだ？私のナイスバディに魅了された？直接言えばいいよ、誠実な人が好きだから。！",
      "星アップ": "進め！どんな困難にぶつかってもとまらずに進むんだ！",
      "覚醒": "身長がもっと高ければいいのにな・・・って盗み聞きしないでよ！",
      "親密アイテム1": "ボーっとしてないで、早く手の届かない所を塗ってくれ。なに？恥ずかしい？私も気にしてないのに、なんでおまえが逆に照れちゃってんだ。",
      "親密アイテム2": "はやく手つけなよ！私の体に塗れてない箇所があったら、懲らしめてやるから。",
      "MVP宣言": "私ナポレオンの前に、勝てないものなんてない！",
      "スキル1": "一鉄砲くらえ！",
      "スキル2": "おまえを狙ってるから",
      "奥義1": "砲撃開始！死ぬ覚悟をしとけ！",
      "奥義2": "私の砲声が勝利を宣言している！",
      "死亡SE": "うあ～"
    },
