      "ホーム画面タップ２": "聞いたか？昨日歌舞伎町の芸者がある大物にあたって、確かあの人も城主様だったらしい。あの二人はさぞいい夜を過ごしたよな、あははは！えっ、あの人ってあんただったのか？そうか、へへ…",
      "ホーム画面タップ３": "私は変化が好きではありません。それは元のルールを破ることを意味します。しかし、いい変化もあります。例えば、あなたに会えること。",
      "ホーム画面下着状態": "いやだ、今までずっと練習していたのに、これは人に見られたら恥ずかしいことだ。",
      "ホーム画面下着タップ1": "あんた！見ちゃだめ！早く目を閉じて！くっ、動けないね。あんた、手伝って、こんな姿、人に見られたくない",
      "ホーム画面下着タップ2": "釣りをする際は、心の中で60秒まで数えてから竿を引き揚げるのが重要です！おっと、失敗しましたか。今度は必ず釣り上げます!",
