    "cv": "ゆね",
    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA2MjdfMTA5/MDAxNjg3ODQ3NTk1NDA3.s3-MCd6GUrUF1EEoQVIAsClhsv24Hyht1EIGMnPV95sg.VngwS-LFc7oHMPbdJX81T_HFJXOyCrw_EJFVc8fgTOsg.JPEG/%EB%A9%94%EC%9D%B4%EB%A6%B0.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "私は至高の魔法使い、マリーンだ! どんな願いでも叶えてあげる......ただし、あなたの大切なものと引き替えにね。 さて、私と契約する覚悟はあるのか？",
      "ホーム画面タップ１": "人は皆、自分の運命から逃れられない。そして、私は他人の運命を覗き見ることができる唯一の存在なのだ! 自分の運命はなんなのって？ふん、あんたみたいな嫌なやつには教えない！",
      "ホーム画面タップ２": "美少女が好きなようだね？ 私に祈願してみないか？ 大丈夫だよ、そのかわりちょっとだけあなたの気運をもらうだけだから、いい話だろう！？ 試してみないか？",
      "ホーム画面タップ３": "願いを叶えるために、これまで多くの人と出会ってきた。 やはり、人間は欲深い生き物なんだな。 でも、二人だけは違う。一人はあなたで、もう一人は......誰だと思う？",
      "ホーム画面下着状態": "へへ！ そうだそうだ、相打ちだ! 喧嘩だ！ 混乱になれ! 私はそれが見たいんだ! ハハハ！",
      "ホーム画面下着タップ1": "俺を怒らせたらこうなるんだ! もっと激しい喧嘩になるまでお手伝いしてあげよう！水鉄砲、ショット！",
      "ホーム画面下着タップ2": "うわああ！ばれちゃった！？ 私の魔法は強力なのに......待て、私の尻尾に何をつけたんだ......ああっ!",
      "ランクアップ": "これで自らの運命をはっきり見えるのでしょう！",
      "覚醒": "もっと上級の魔法を身に着けたらもっと堕落した魂を手に入れられる！",
      "調教道具1": "------------------------------",
      "MVP宣言": "私は見えたよ、壊滅されるのはあなたの運命なのだ！",
      "プレゼント-挨拶": "さて、私と取引しないか？",
      "プレゼント-感謝1": "う！なにこの美食！すごい！",
      "プレゼント-感謝2": "いいだろう！１つだけ、タダで願いを叶えてあげよるよ！",
      "プレゼント-感謝3": "いつまでも一緒にいて、おいしい料理を作ってほしい！",
      "クローズアップ": "------------------------------",
      "スキル1": "は…",
      "スキル2": "おや！…",
      "スキル3": "うらら…",
      "奥義1": "自然からの恩恵（恵み）だ！",
      "奥義2": "これが私の魔法よ、ハハハ！",
      "死亡": "……私の弱点、バレたのか？"
    },
