      "メインページでタップ２": "まったく、弱い者いじめをしている輩をやっつけた後に、なぜか分からないが毎回彼らに姉貴呼ばわりされてしまうな・・・",
      "メインページでタップ３": "私の刀が気になるのか？目の付け所が良いな！これは私が噂の妖怪、大天狗様から頂いたものだ！切れ味抜群の上、夜の照明としても使えるのだぞ！",
