    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA2MjlfMjUg/MDAxNjg4MDIyNTQzMzI3.Ap_2bPro_ThUGTHvucXzTvRi0FdPvAh_ILmHnBygaI8g.N9aw-Q9qZfc_nt_6rUR5w5xA-mWg5keF5H2vJcdAAOEg.PNG/%EB%B2%A4%EC%BC%80%EC%9D%B4.png?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "こんにちは、義経様の居場所を教えてくれませんか？義経様が居なければ私は不完全です！逆も同じです。だから義経様の居場所を教えてくれたら、何だってしてあげられますよ。",
      "ホーム画面タップ１": "義経様があなたのことを何度も話していました、義経様に気に入られる術は何なのでしょう？教えていただけませんか？私もあなたのようになりたいんです！",
      "ホーム画面タップ２": "あなたも私にキノコを食べさせたいのですか？キノコなんて大っ嫌いです！やっぱりいつも私にキノコを食べさせたりしない義経様が最高です！",
      "ホーム画面タップ３": "ふむ！森蘭丸のやつに義経様は無敵で、天下最強だって伝えてください！不満があるなら……あってもしょうがない、だって義経様は最強ですもん！",
      "ホーム画面下着状態": "嫌だ！歯磨きは嫌だ！義経様にしか歯を磨かれたくありません！",
      "ホーム画面下着タップ1": "義経様が私の歯を磨くのは久しぶりなので、その感触が懐かしいのでしょうか？私にとっても懐かしいですし、義経様にとっても懐かしいはず！もう待っていられませんね。",
      "ホーム画面下着タップ2": "そんなのだめ……あ！気持ち…いいけど……う～ん……あ……けど……あ！ヤバい！",
      "ランクアップ": "義経様のためにも、もっともっと頑張ります！",
      "覚醒": "義経様！私は少しずつ強くなっています！",
      "調教道具1": "------------------------------",
      "MVP宣言": "義経様に恥はかかせませんよ！",
      "プレゼント-挨拶": "またあなたに会えて、嬉しいです！",
      "プレゼント-感謝1": "ありがとう、これは気に入りましたよ！",
      "プレゼント-感謝2": "これを義経様に差し上げます！",
      "プレゼント-感謝3": "キノコ以外なら何でも食べたいです！",
      "クローズアップ": "------------------------------",
      "スキル1": "ヘイヤ！",
      "スキル2": "倒せ！",
      "スキル3": "さようなら！",
      "奥義1": "私をなめるなよ！",
      "奥義2": "義経様の為に戦います！",
      "死亡": "もう義経様に会えないですね、う～"
    },
