    "illustUrl": "https://nng-phinf.pstatic.net/MjAyMzA1MjRfNjEg/MDAxNjg0OTA3MDI4MjMz.9Eo_39wWpT6Xq4hKrAyCfVuThyBlQtsnM9laHwgF6ewg.KzxNYrEbN1PEjpjUFHhxeS2ga6KF3WLVeFtmFNKj_2Yg.JPEG/%EB%8B%A4%EC%B9%98%EB%B0%94%EB%82%98_%EA%B8%B4%EC%B9%98%EC%9A%94.jpg?type=w1678",
    "illustSource": "少女ウォーズ@wiki",
    "illustCredit": "少女ウォーズ@wiki / 公式スチル",
    "dialogues": {
      "召喚獲得": "こんにちは、私は立花家の次女、立花誾千代です！これからお姉さまよりも強くなります、一緒に頑張りましょう！",
      "ホーム画面タップ１": "他人に触らせてはダメってお姉さまが言ってました。それじゃああなたの手を切り落としたらどうでしょうか？",
      "ホーム画面タップ２": "私もお姉さまのようなすごい人になるために、悪い人を懲らしめる方法をいろいろ勉強しています。試してみてはいかがですか？",
      "ホーム画面タップ３": "この世界は複雑で、わからないことだらけですから、あなたを縛り付けて、ゆっくり教えてもらうのはどうでしょうか？とってもいいですよねー。",
      "ホーム画面下着状態": "ん？こういう変わったものを着るのは初めてで、胸がちょっと気持ち悪いですね。揉んでもらえませんか？",
      "ホーム画面下着タップ1": "あのう、服が脱げないんです、脱がせてくれませんか？",
      "ホーム画面下着タップ2": "今日は一緒に買い物に行ってくれてありがとうございました！とても気に入ったので、後で着たところを見せたいです。",
      "ランクアップ": "お姉さまのように強くなって、名を世界の果てまで届けましょう！",
      "覚醒": "えへへ、もっともっと頑張って、最上級の苦痛を与えてみせます。",
      "調教道具1": "------------------------------",
      "MVP宣言": "人をいじめるのは得意なんです!",
      "プレゼント-挨拶": "また会えましたね。私の新しい発明、「ホラーゲーム」を試してみませんか？",
      "プレゼント-感謝1": "美味しいです、もっと頂けませんか？",
      "プレゼント-感謝2": "食べ終わったら一緒にゲームでもしましょうよ！",
      "プレゼント-感謝3": "この美食はお姉さまに食べさせたいです！",
      "クローズアップ": "------------------------------",
      "スキル1": "ハ！…",
      "スキル2": "エイ！ハ！…",
      "スキル3": "私の弓矢を味わってください！",
      "奥義1": "どまん中命中！ハハハ！",
      "奥義2": "この矢で、胸を貫いて差し上げましょう!",
      "死亡": "もう..二度と..お姉さまに会えません..か？"
    },
